/* Browser-local fictional sample domain. Never use as a security boundary. */
(function(root){'use strict';const R=root.Reunion;
const ALBUMS=[{id:1,name:'フォトアルバム',description:'みんなの思い出を、ここに。',position:1,visible:true}];
function refreshDemoRoster(s){if(s.demoRosterVersion===2)return;for(let cl=1;cl<=10;cl++){let index=0;const stock=s.people.filter(p=>p.class===cl&&/^sample[0-9]+@example\.test$/.test(p.email)&&p.note==='架空データ・実在の卒業生とは関係ありません'&&p.revision===1).sort((a,b)=>Number(!R.active(a))-Number(!R.active(b))||a.id-b.id);for(const p of stock){const profile=R.sampleProfile(cl,index++),before={name:p.name,display:p.display};const old=p.name;p.name=profile.name;p.kana=profile.kana;if(p.display===old)p.display=profile.name;}let n=s.people.filter(p=>p.class===cl&&R.active(p)).length;while(n<16){const id=Math.max(0,...s.people.map(p=>p.id))+1,profile=R.sampleProfile(cl,index++);s.people.push({id,number:'K87-'+String(id).padStart(5,'0'),class:cl,name:profile.name,kana:profile.kana,oldname:'',display:profile.name,email:'sample'+id+'@example.test',address:'愛知県架空市見本町1-2-3',postal:'000-0000',phone:'000-0000-0000',payer:'サンプル'+String(id).padStart(3,'0'),public:true,status:'active',amount:s.settings.fee,note:'架空データ・実在の卒業生とは関係ありません',created:new Date().toISOString(),revision:1,role:'participant'});n++;}}s.demoRosterVersion=2;R.audit(s,'サンプル更新','架空の見本名簿を更新','demo',null,{people:s.people.length},'既存の申込・入金・投稿・独自編集を保持し、各組16人前後の見本へ更新');}
function prepare(s){refreshDemoRoster(s);s.settings.classSize??=47;if(s.settings.dateLabel==='2028年○月○日（未定）')s.settings.dateLabel='2028年10月31日（火）（仮）';s.inquiries??=[];s.albums??=R.clone(ALBUMS);if(!s.albumTemplateVersion){const oldNames=['当日の様子','集合写真','懇親会'],oldDescriptions=['再会のひとときを、写真で。','懐かしい顔が、勢ぞろい。','話の続きは、同じテーブルで。'];const defaults=s.albums.length===3&&s.albums.every((a,i)=>a.id===i+1&&a.name===oldNames[i]&&a.description===oldDescriptions[i]&&a.position===i+1&&a.visible===true)&&!s.logs.some(l=>l.action==='アルバム設定');if(defaults){const before=R.clone(s.albums);s.albums=R.clone(ALBUMS);s.photos.forEach(p=>p.albumId=1);R.audit(s,'システム（サンプル）','見本アルバムの整理','albums',before,s.albums,'固定の3分類から自由設定へ。写真は保持。');}s.albumTemplateVersion=1;}if(!s.classContacts){s.classContacts=[];for(let cl=1;cl<=10;cl++)s.people.filter(p=>p.class===cl&&R.active(p)).slice(0,2).forEach((p,j)=>s.classContacts.push({id:s.classContacts.length+1,userId:p.id,class:cl,position:j+1}));}s.photos.forEach((p,i)=>{p.albumId??=1;p.album=s.albums.find(a=>a.id===p.albumId)?.name||'アルバム未設定';});}
function admin(s,uid,onlyOwner=false){const p=s.people.find(p=>p.id===uid);if(!p||!['owner','organizer'].includes(p.role)||onlyOwner&&p.role!=='owner')throw new Error(onlyOwner?'代表幹事だけが設定できます。':'幹事のログインが必要です。');return p;}
function required(v,max=10000){v=String(v??'').trim();if(!v||v.length>max)throw new Error('必須項目を入力し、長すぎる内容を短くしてください。');return v;}
function inquiry(s,d,uid=null){prepare(s);if(!/^(?:[0-9]|10)$/.test(String(d.class??'')))throw new Error('クラスを選択してください。');const email=required(d.email,254).toLowerCase();if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('返信用メールアドレスを確認してください。');const x={id:Math.max(0,...s.inquiries.map(i=>i.id))+1,userId:uid,class:Number(d.class),name:required(d.name,200),email,subject:required(d.subject,200),body:required(d.body),status:'new',assignee:null,replies:[],created:new Date().toISOString()};s.inquiries.push(x);R.audit(s,uid?'申込者（サンプル）':'未ログイン（サンプル）','問い合わせ受付','inquiry:'+x.id,null,{status:x.status},'架空の公開フォーム');return x;}
function reply(s,id,body,uid){prepare(s);const a=admin(s,uid),i=s.inquiries.find(i=>i.id===id);if(!i)throw new Error('問い合わせがありません。');const r={id:i.replies.length+1,body:required(body),actor:a.name,created:new Date().toISOString()};i.replies.push(r);i.status='in_progress';i.assignee=uid;s.mail.push({id:s.mail.length+1,to:i.email,subject:'【岡崎北1987同窓会】お問い合わせへの回答 #'+id,body:r.body,at:r.created,status:'開発用・未送信'});R.audit(s,a.name,'問い合わせ返信を記録','inquiry:'+id,null,{reply:r.id,to:i.email},'開発用メールへ記録・実送信なし');}
function status(s,id,st,assignee,reason,uid){const a=admin(s,uid),i=s.inquiries.find(i=>i.id===id);if(!i||!['new','in_progress','closed'].includes(st))throw new Error('問い合わせと対応状況を確認してください。');if(assignee)admin(s,assignee);const before={status:i.status,assignee:i.assignee};i.status=st;i.assignee=assignee||null;R.audit(s,a.name,'問い合わせ対応状況変更','inquiry:'+id,before,{status:st,assignee:i.assignee},required(reason));}
function contacts(s,cl){prepare(s);return s.classContacts.filter(c=>c.class===cl).map(c=>({...c,person:s.people.find(p=>p.id===c.userId)})).filter(c=>c.person&&c.person.class===cl&&R.active(c.person)).sort((a,b)=>a.position-b.position||a.id-b.id);}
function contactAdd(s,cl,uid,position,reason,actorId){prepare(s);const a=admin(s,actorId,true),p=s.people.find(p=>p.id===uid);if(!Number.isInteger(cl)||cl<1||cl>10||!p||p.class!==cl||!R.active(p)||!Number.isInteger(position)||position<1||position>3)throw new Error('同じクラスの参加予定者と表示順1〜3を指定してください。');if(s.classContacts.some(c=>c.class===cl&&c.userId===uid))throw new Error('すでに指定されています。');if(s.classContacts.filter(c=>c.class===cl).length>=3)throw new Error('クラス幹事の表示は最大3名です。');const c={id:Math.max(0,...s.classContacts.map(c=>c.id))+1,userId:uid,class:cl,position};s.classContacts.push(c);R.audit(s,a.name,'クラス幹事表示を指定','class:'+cl,null,c,required(reason));}
function contactRemove(s,id,reason,uid){const a=admin(s,uid,true),c=s.classContacts.find(c=>c.id===id);if(!c)throw new Error('指定がありません。');s.classContacts=s.classContacts.filter(c=>c.id!==id);R.audit(s,a.name,'クラス幹事表示を解除','class:'+c.class,c,null,required(reason));}
function albumSave(s,d,uid){prepare(s);const a=admin(s,uid),id=Number(d.id||0),before=id?s.albums.find(a=>a.id===id):null;if(id&&!before)throw new Error('アルバムがありません。');const x={id:id||Math.max(0,...s.albums.map(a=>a.id))+1,name:required(d.name,200),description:String(d.description||'').slice(0,1000),position:Number(d.position),visible:d.visible==='yes'};if(!Number.isInteger(x.position)||x.position<1||x.position>999)throw new Error('表示順は1〜999です。');R.audit(s,a.name,'アルバム設定','album:'+x.id,before,x,required(d.reason));if(before)Object.assign(before,x);else s.albums.push(x);prepare(s);return x;}
function photoMove(s,id,albumId,reason,uid){const a=admin(s,uid),p=s.photos.find(p=>p.id===id),album=s.albums.find(a=>a.id===albumId);if(!p||!album)throw new Error('写真とアルバムを確認してください。');const before=p.albumId;p.albumId=albumId;p.album=album.name;R.audit(s,a.name,'写真のアルバム変更','photo:'+id,{albumId:before},{albumId},required(reason));}
function visiblePhotos(s,album=0){prepare(s);return s.photos.filter(p=>p.published&&(!album||p.albumId===album)&&s.albums.some(a=>a.id===p.albumId&&a.visible));}
const C={prepare,inquiry,reply,status,contacts,contactAdd,contactRemove,albumSave,photoMove,visiblePhotos};root.Community=C;if(typeof module!=='undefined')module.exports=C;
})(typeof globalThis!=='undefined'?globalThis:this);
